package com.iare.club.entity;import jakarta.persistence.*;import java.time.Instant;
@Entity @Table(name="merchant_payment_config_history",indexes=@Index(name="idx_payment_config_history_date",columnList="changed_at"))public class MerchantPaymentConfigHistory{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="config_id",nullable=false)private Long configId;@Column(name="merchant_name",nullable=false,length=120)private String merchantName;@Column(name="upi_id",nullable=false,length=180)private String upiId;@Column(nullable=false)private boolean active;@Column(name="changed_by",nullable=false,length=180)private String changedBy;@Column(name="changed_at",nullable=false)private Instant changedAt;protected MerchantPaymentConfigHistory(){}public MerchantPaymentConfigHistory(MerchantPaymentConfig c,String admin,Instant at){configId=c.getId();merchantName=c.getMerchantName();upiId=c.getUpiId();active=c.isActive();changedBy=admin;changedAt=at;}public String getMerchantName(){return merchantName;}public String getUpiId(){return upiId;}public boolean isActive(){return active;}public String getChangedBy(){return changedBy;}public Instant getChangedAt(){return changedAt;}}
